import React, { useState, useEffect } from 'react';
import { useTable, useSortBy, useFilters } from 'react-table';
import 'react-datepicker/dist/react-datepicker.css';
import '../styles/List.css';
import '../styles/Actions.css';
import { RESERVATIONS_URL } from '../config';
import ReservationForm from './ReservationForm';
import { useLocation } from './AreaContext';

const Actions = ({ user, view, filter }) => {
  const [data, setData] = useState([]);
  const [selectedReservation, setSelectedReservation] = useState(null);
  const { selectedLocation } = useLocation();

  const fetchData = () => {
    fetch(`${RESERVATIONS_URL}${selectedLocation}.json`)
      .then((response) => response.json())
      .then((data) => {
        let userReservations;

        if (view === 'ATCView') {
          // Show all reservations regardless of user.cid
          userReservations = data.filter(
            (reservation) => reservation.status !== 'cancelled'
          );
        } else {
          // Filter reservations based on user.cid
          userReservations = data.filter(
            (reservation) =>
              Number(reservation.creator) === Number(user.cid) &&
              reservation.status !== 'cancelled'
          );
        }

        const processedData = userReservations.map((reservation) => {
          const airspaces = reservation.areas.map((area) => area.area_id).join(', ');
          const lower = Math.min(...reservation.areas.map((area) => area.lower));
          const upper = Math.max(...reservation.areas.map((area) => area.upper));
          const isAltitudesDifferent = reservation.areas.some(
            (area) => area.lower !== lower || area.upper !== upper
          );
          return { ...reservation, airspaces, lower, upper, isAltitudesDifferent };
        });

        setData(processedData);
      })
      .catch((error) => {
        console.error('Error loading or processing JSON data:', error);
      });
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 60000);
    return () => clearInterval(interval);
  }, [user]);

  const columns = React.useMemo(
    () => [
      { Header: 'ID', accessor: 'reservation_id' },
      { Header: 'Airspace', accessor: 'airspaces' },
      { Header: 'Lower', accessor: 'lower' },
      { Header: 'Upper', accessor: 'upper' },
      { Header: 'Start Date', accessor: 'start' },
      { Header: 'End Date', accessor: 'end' },
      { Header: 'Status', accessor: 'status' },
      { Header: 'NRAC', accessor: 'nbr_acft' },
    ],
    []
  );

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    setFilter,
  } = useTable(
    {
      columns,
      data,
    },
    useFilters,
    useSortBy
  );
  
  useEffect(() => {
    setFilter('airspaces', filter || '');
  }, [filter, setFilter]);

  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    const day = String(date.getUTCDate()).padStart(2, '0');
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const year = date.getUTCFullYear();
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}`;
  };

  const handleRowClick = (reservation) => {
    setSelectedReservation(reservation.reservation_id);
  };

  const closeModal = () => {
    setSelectedReservation(null);
  };

  // Function to get background color based on status
  const getRowBackgroundColor = (status) => {
    switch (status) {
      case 'pending':
        return '#ea9750';
      case 'active':
        return '#40bb78';
      case 'proposal':
        return '#50a3ea';
      case 'cancelled':
        return '#ea5056';
      default:
        return 'transparent';
    }
  };

  const isEndingSoon = (endTimestamp, status) => {
    if (status !== 'active') return false;
  
    const nowUtc = Date.now(); // UTC time
    const endUtc = new Date(endTimestamp).getTime(); // UTC timestamp  
    return endUtc - nowUtc < 10 * 60 * 1000 && endUtc > nowUtc;
  };

  return (
    <div className="list-container">
      <p>Actions</p>

      {/* Table */}
      <table className="list-table" {...getTableProps()}>
        <thead>
        {headerGroups.map((headerGroup) => {
          const headerGroupProps = headerGroup.getHeaderGroupProps();
          const { key, ...rest } = headerGroupProps;
          return (
            <tr key={key} {...rest}>
              {headerGroup.headers.map((column) => {
                const headerProps = column.getHeaderProps(column.getSortByToggleProps());
                const { key, ...rest } = headerProps;
                return (
                  <th key={key} {...rest} style={{ cursor: 'pointer', userSelect: 'none' }}>
                    {column.render('Header')}
                    {column.isSorted ? (column.isSortedDesc ? ' ▼' : ' ▲') : ''}
                  </th>
                );
              })}
            </tr>
          );
        })}
        </thead>
        <tbody {...getTableBodyProps()}>
          {rows.length > 0 ? (
            rows.map((row) => {
              prepareRow(row);
              const { key: rowKey, ...rowRest } = row.getRowProps();
              return (
                <tr
                  key={rowKey}
                  {...rowRest}
                  onClick={() => handleRowClick(row.original)}
                  style={{
                    backgroundColor: getRowBackgroundColor(row.original.status),
                    cursor: 'pointer',
                  }}
                >
                  {row.cells.map((cell) => {
                    const { key: cellKey, ...cellRest } = cell.getCellProps();

                    if (cell.column.id === 'start') {
                      return <td key={cellKey} {...cellRest}>{formatDate(cell.value)}</td>;
                    }

                    if (cell.column.id === 'end') {
                      const isFlashing = isEndingSoon(cell.value, row.original.status);
                      return (
                        <td
                          key={cellKey}
                          {...cellRest}
                          className={isFlashing ? 'flashing-red' : ''}
                        >
                          {formatDate(cell.value)}
                        </td>
                      );
                    }

                    if (cell.column.id === 'lower' || cell.column.id === 'upper') {
                      const isAltitudesDifferent = row.original.isAltitudesDifferent;
                      const value = cell.value === 0 ? 'SFC' : cell.value === 999 ? 'UNL' : cell.value;
                      return (
                        <td
                          key={cellKey}
                          {...cellRest}
                          style={{ color: isAltitudesDifferent ? 'orange' : 'black' }}
                        >
                          {value}
                        </td>
                      );
                    }

                    return <td key={cellKey} {...cellRest}>{cell.render('Cell')}</td>;
                  })}
                </tr>
              );
            })
          ) : (
            <tr>
              <td colSpan={columns.length} style={{ textAlign: 'center', color: '#888' }}>
                No reservations found
              </td>
            </tr>
          )}
        </tbody>

      </table>

      {/* Modal */}
      {selectedReservation && (
        <ReservationForm
          user={user}
          view={view}
          reservationId={selectedReservation}
          isOpen={!!selectedReservation}
          onClose={closeModal}
          mode="edit"
        />
      )}
    </div>
  );
};

export default Actions;
